    def _generate_dashboard_js(self, dashboard: Dict[str, Any]) -> str:
        """Generar JavaScript del dashboard"""

        js_template = f"""
        <script>
        // MAXIMUSPRIME Canva Agent - Dashboard JavaScript
        // Dashboard ID: {dashboard['id']}
        // Generado: {datetime.datetime.now().isoformat()}

        // Configuración global
        const DashboardConfig = {{
            dashboardId: '{dashboard['id']}',
            sessionId: '{self.session_id}',
            refreshInterval: 30000, // 30 segundos
            widgets: {json.dumps([w['id'] for w in dashboard['widgets']])},
            dataConnections: {json.dumps(dashboard['data_connections'])},
            predictiveModels: {json.dumps(dashboard['predictive_models'])},
            lastUpdated: null
        }};

        // Estado del dashboard
        const DashboardState = {{
            isUpdating: false,
            predictions: {{}},
            dataCache: {{}},
            widgetStates: {{}},
            alerts: []
        }};

        // Inicialización
        document.addEventListener('DOMContentLoaded', async function() {{
            console.log('MAXIMUSPRIME Dashboard inicializando...');

            // Inicializar Canva SDK si está disponible
            if (typeof Canva !== 'undefined') {{
                await initializeCanvaSDK();
            }}

            // Cargar datos iniciales
            await loadAllData();

            // Ejecutar predicciones iniciales
            await runAllPredictions();

            // Actualizar interfaz
            updateLastUpdated();
            startAutoRefresh();

            console.log('Dashboard listo - Modelos activos:', DashboardConfig.predictiveModels.length);
        }});

        // Funciones principales
        async function initializeCanvaSDK() {{
            try {{
                // Configurar Canva Apps SDK
                await Canva.initialize({{
                    // Configuración específica
                }});

                console.log('Canva SDK inicializado correctamente');

                // Suscribirse a eventos de Canva
                Canva.Design.onChange(async (design) => {{
                    console.log('Diseño Canva actualizado', design);
                    await syncWithCanvaDesign(design);
                }});

            }} catch (error) {{
                console.warn('Canva SDK no disponible, continuando sin integración', error);
            }}
        }}

        async function loadAllData() {{
            DashboardState.isUpdating = true;
            showUpdatingState(true);

            try {{
                // Cargar datos de todas las conexiones
                for (const connection of DashboardConfig.dataConnections) {{
                    const data = await fetchData(connection);
                    DashboardState.dataCache[connection.id] = data;
                }}

                // Notificar a widgets
                for (const widgetId of DashboardConfig.widgets) {{
                    if (window[`updateWidget_${{widgetId}}`]) {{
                        window[`updateWidget_${{widgetId}}`](DashboardState.dataCache);
                    }}
                }}

                console.log('Datos cargados:', Object.keys(DashboardState.dataCache).length, 'conexiones');

            }} catch (error) {{
                console.error('Error cargando datos:', error);
                showError('Error cargando datos: ' + error.message);
            }} finally {{
                DashboardState.isUpdating = false;
                showUpdatingState(false);
            }}
        }}

        async function runAllPredictions() {{
            console.log('Ejecutando predicciones...');

            for (const model of DashboardConfig.predictiveModels) {{
                try {{
                    const prediction = await executePredictiveModel(model);
                    DashboardState.predictions[model.id] = prediction;

                    // Actualizar widgets relacionados
                    updateWidgetsWithPrediction(model.id, prediction);

                    // Verificar alertas
                    checkPredictionAlerts(model.id, prediction);

                }} catch (error) {{
                    console.warn(`Error en modelo ${{model.id}}:`, error);
                }}
            }}

            // Actualizar estadísticas
            updatePredictionsStats();
        }}

        async function executePredictiveModel(model) {{
            // Implementación del modelo predictivo
            // Esto puede ser una llamada a API, cálculo local, etc.

            switch (model.type) {{
                case 'regression':
                    return await runRegressionModel(model);
                case 'classification':
                    return await runClassificationModel(model);
                case 'time_series':
                    return await runTimeSeriesModel(model);
                case 'neural_network':
                    return await runNeuralNetworkModel(model);
                default:
                    throw new Error(`Tipo de modelo no soportado: ${{model.type}}`);
            }}
        }}

        // Funciones específicas de modelos
        async function runRegressionModel(model) {{
            // Implementar regresión lineal/múltiple
            const data = getModelData(model);

            // Coeficientes del modelo (podrían venir de entrenamiento previo)
            const coefficients = model.coefficients || [0.5, 0.3, 0.2];

            // Calcular predicción
            let prediction = coefficients[0]; // intercept
            for (let i = 0; i < data.length; i++) {{
                prediction += coefficients[i + 1] * (data[i] || 0);
            }}

            // Calcular confianza
            const confidence = calculateRegressionConfidence(data, coefficients);

            return {{
                value: prediction,
                confidence: confidence,
                type: 'regression',
                timestamp: new Date().toISOString(),
                modelId: model.id
            }};
        }}

        async function runTimeSeriesModel(model) {{
            // Implementar ARIMA/ETS/Prophet simplificado
            const historicalData = getTimeSeriesData(model);

            if (historicalData.length < 2) {{
                return {{
                    value: 0,
                    confidence: 0,
                    forecast: [],
                    type: 'time_series',
                    message: 'Datos insuficientes'
                }};
            }}

            // Pronóstico simple (promedio móvil)
            const window = Math.min(5, historicalData.length);
            const lastValues = historicalData.slice(-window);
            const avg = lastValues.reduce((a, b) => a + b, 0) / lastValues.length;

            // Generar forecast
            const forecast = [];
            for (let i = 1; i <= (model.horizon || 7); i++) {{
                forecast.push(avg * (1 + (model.trend || 0) * i));
            }}

            return {{
                value: forecast[0],
                confidence: calculateTimeSeriesConfidence(historicalData),
                forecast: forecast,
                type: 'time_series',
                horizon: model.horizon || 7
            }};
        }}

        // Funciones de utilidad
        function updateLastUpdated() {{
            const now = new Date();
            DashboardConfig.lastUpdated = now;
            document.getElementById('last-updated').querySelector('span').textContent = 
                now.toLocaleTimeString();
        }}

        function showUpdatingState(isUpdating) {{
            const widgets = document.querySelectorAll('.widget');
            widgets.forEach(widget => {{
                if (isUpdating) {{
                    widget.classList.add('updating');
                }} else {{
                    widget.classList.remove('updating');
                }}
            }});
        }}

        function showError(message) {{
            const alertsDiv = document.getElementById('dashboard-alerts');
            const alert = document.createElement('div');
            alert.className = 'alert alert-error';
            alert.innerHTML = `
                <i class="fas fa-exclamation-triangle"></i>
                <span>${{message}}</span>
                <button onclick="this.parentElement.remove()">&times;</button>
            `;
            alertsDiv.appendChild(alert);

            // Auto-remover después de 10 segundos
            setTimeout(() => alert.remove(), 10000);
        }}

        function startAutoRefresh() {{
            setInterval(async () => {{
                if (!DashboardState.isUpdating) {{
                    await loadAllData();
                    await runAllPredictions();
                    updateLastUpdated();
                }}
            }}, DashboardConfig.refreshInterval);
        }}

        // Funciones disponibles globalmente
        window.refreshAllData = loadAllData;
        window.refreshWidget = async function(widgetId) {{
            // Recargar datos específicos del widget
            if (window[`refreshWidget_${{widgetId}}`]) {{
                await window[`refreshWidget_${{widgetId}}`]();
            }}
        }};

        window.exportDashboard = function() {{
            // Exportar dashboard como imagen/PDF
            const data = {{
                dashboard: DashboardConfig,
                state: DashboardState,
                timestamp: new Date().toISOString()
            }};

            const blob = new Blob([JSON.stringify(data, null, 2)], {{type: 'application/json'}});
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `maximusprime-dashboard-${{DashboardConfig.dashboardId}}.json`;
            a.click();

            console.log('Dashboard exportado');
        }};

        // Estadísticas en tiempo real
        let predictionsCount = 0;
        setInterval(() => {{
            document.getElementById('predictions-per-minute').textContent = predictionsCount;
            predictionsCount = 0;
        }}, 60000);

        function updatePredictionsStats() {{
            predictionsCount += Object.keys(DashboardState.predictions).length;
        }}

        // Función para integrar con Canva Data API
        async function syncWithCanvaDesign(design) {{
            // Sincronizar datos del dashboard con el diseño Canva
            if (Canva && Canva.Data) {{
                try {{
                    await Canva.Data.set({{
                        dashboardId: DashboardConfig.dashboardId,
                        predictions: DashboardState.predictions,
                        lastUpdated: DashboardConfig.lastUpdated
                    }});

                    console.log('Datos sincronizados con Canva');
                }} catch (error) {{
                    console.warn('Error sincronizando con Canva:', error);
                }}
            }}
        }}

        // Inicializar widgets específicos
        {self._generate_widget_initialization_js(dashboard['widgets'])}
        </script>
        """

        return js_template

    def _create_canva_design(self, title: str, elements: List[Dict], design_type: str) -> Dict[str, Any]:
        """Crear un diseño Canva con los elementos proporcionados"""

        design_id = f"design-{hashlib.md5(title.encode()).hexdigest()[:12]}"

        # Dimensiones según tipo
        dimensions = {
            "presentation": {"width": 1920, "height": 1080},
            "social_media": {"width": 1200, "height": 630},
            "document": {"width": 2100, "height": 2970},  # A4
            "dashboard": {"width": 1600, "height": 900},
            "infographic": {"width": 1200, "height": 1800}
        }.get(design_type, {"width": 1200, "height": 800})

        design = CanvaDesign(
            design_id=design_id,
            title=title,
            type=design_type,
            dimensions=dimensions,
            elements=elements,
            metadata={
                "created_by": "MAXIMUSPRIME Canva Agent",
                "version": "4.0",
                "session_id": self.session_id,
                "predictive_elements": len([e for e in elements if e.get("predictive", False)])
            },
            created_at=datetime.datetime.now().isoformat(),
            modified_at=datetime.datetime.now().isoformat()
        )

        self.recent_designs.append(design)

        return {
            "design": design,
            "embed_code": design.to_html_embed(),
            "preview_url": f"https://canva.com/design/{design_id}/view",
            "edit_url": f"https://canva.com/design/{design_id}/edit"
        }

    def generate_canva_app(self, app_config: Dict[str, Any]) -> Dict[str, Any]:
        """
        Generar una aplicación Canva Apps SDK completa

        Args:
            app_config: Configuración de la aplicación
                - name: Nombre de la app
                - description: Descripción
                - capabilities: Capacidades requeridas
                - ui_elements: Elementos de interfaz
                - data_sources: Fuentes de datos
                - predictive_features: Características predictivas
        """

        app_id = f"app-{hashlib.md5(app_config['name'].encode()).hexdigest()[:8]}"

        # Generar estructura de la app
        app_structure = {
            "appId": app_id,
            "name": app_config["name"],
            "version": "1.0.0",
            "manifest": self._generate_app_manifest(app_config),
            "ui": self._generate_app_ui(app_config),
            "logic": self._generate_app_logic(app_config),
            "predictive_models": app_config.get("predictive_features", []),
            "integrations": app_config.get("integrations", {})
        }

        # Generar código completo
        app_code = self._generate_app_code(app_structure)

        # Crear archivos de la app
        app_files = {
            "manifest.json": json.dumps(app_structure["manifest"], indent=2),
            "ui.js": app_code["ui"],
            "logic.js": app_code["logic"],
            "styles.css": app_code["styles"],
            "README.md": self._generate_app_readme(app_structure)
        }

        return {
            "app_id": app_id,
            "app_structure": app_structure,
            "app_files": app_files,
            "installation_instructions": self._get_app_installation_instructions(app_structure),
            "test_url": f"https://canva.com/apps/test/{app_id}"
        }

    def _generate_app_manifest(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Generar manifest de app para Canva Apps SDK"""

        return {
            "name": config["name"],
            "id": f"com.maximusprime.{config['name'].lower().replace(' ', '-')}",
            "version": "1.0.0",
            "author": "MAXIMUSPRIME Canva Agent",
            "description": config.get("description", "Aplicación predictiva para Canva"),
            "permissions": [
                "design:read",
                "design:write",
                "user:read",
                "data:read",
                "data:write"
            ],
            "capabilities": config.get("capabilities", ["ui", "data", "export"]),
            "entryPoints": [
                {
                    "type": "panel",
                    "id": "main-panel",
                    "title": config["name"]
                }
            ],
            "icons": {
                "16": "icon16.png",
                "48": "icon48.png",
                "128": "icon128.png"
            }
        }

    def analyze_canva_design(self, design_data: Dict[str, Any]) -> Dict[str, Any]:
        """
        Analizar un diseño Canva desde múltiples perspectivas

        Args:
            design_data: Datos del diseño Canva o URL
        """

        analysis = {
            "design_analysis": {},
            "predictive_potential": {},
            "optimization_recommendations": [],
            "accessibility_score": 0,
            "performance_metrics": {},
            "seo_analysis": {},
            "conversion_potential": {}
        }

        # Análisis de diseño
        if "elements" in design_data:
            elements = design_data["elements"]

            # Análisis de elementos
            element_types = {}
            text_content = []
            colors = []

            for element in elements:
                elem_type = element.get("type", "unknown")
                element_types[elem_type] = element_types.get(elem_type, 0) + 1

                if elem_type == "text":
                    text_content.append(element.get("content", ""))

                if "style" in element and "color" in element["style"]:
                    colors.append(element["style"]["color"])

            analysis["design_analysis"]["element_distribution"] = element_types
            analysis["design_analysis"]["color_palette"] = list(set(colors))
            analysis["design_analysis"]["text_volume"] = len(" ".join(text_content).split())

            # Análisis predictivo del contenido
            if text_content:
                analysis["predictive_potential"] = self._analyze_text_for_predictive_potential(
                    " ".join(text_content)
                )

        # Puntuación de accesibilidad
        analysis["accessibility_score"] = self._calculate_accessibility_score(design_data)

        # Recomendaciones de optimización
        recommendations = self._generate_optimization_recommendations(analysis)
        analysis["optimization_recommendations"] = recommendations

        # Análisis SEO (si es diseño web)
        if design_data.get("type") in ["web", "landing_page", "blog"]:
            analysis["seo_analysis"] = self._analyze_seo(design_data)
            analysis["conversion_potential"] = self._analyze_conversion_potential(design_data)

        return analysis

    def _get_activation_message(self) -> str:
        """Mensaje de activación del agente Canva"""

        return f"""
        🎨 MAXIMUSPRIME CANVA AGENT v4.0
        {'='*60}

        ✅ AGENTE ACTIVADO
        • Sesión: {self.session_id}
        • Usuario: {self.user_id}
        • Templates: {len(self.code_templates)} disponibles

        🚀 CAPACIDADES DISPONIBLES:
        1. Creación de dashboards predictivos
