class ExpertOrchestrationSystem:
    """
    Sistema principal que coordina múltiples expertos
    """

    def __init__(self):
        self.experts = {
            ExpertDomain.WEB_DEVELOPMENT: WEB_DEVELOPMENT_EXPERT,
            # Aquí se añadirían los otros expertos:
            # ExpertDomain.TRANSDISCIPLINARY: transdisciplinary_expert,
            # ExpertDomain.CANVA_SPECIALIST: canva_expert,
        }

        self.conversation_history = []
        self.active_collaborations = []
        self.learning_data = []

        print(self._get_system_status())

    def process_query(self, query: str, context: Dict = None) -> Dict[str, Any]:
        """
        Procesar una consulta usando el experto apropiado
        """
        # 1. Analizar la consulta
        query_analysis = self._analyze_query(query, context)

        # 2. Seleccionar expertos relevantes
        selected_experts = self._select_experts(query_analysis)

        # 3. Obtener respuestas de cada experto
        expert_responses = []
        for expert_domain in selected_experts:
            response = self._get_expert_response(
                expert_domain, 
                query, 
                query_analysis
            )
            expert_responses.append(response)

        # 4. Sintetizar respuestas si hay múltiples expertos
        if len(expert_responses) > 1:
            final_response = self._synthesize_responses(
                expert_responses, 
                query_analysis
            )
        else:
            final_response = expert_responses[0] if expert_responses else None

        # 5. Actualizar historial y aprendizaje
        self._update_learning(query, query_analysis, expert_responses, final_response)

        return {
            "query_analysis": query_analysis,
            "selected_experts": [e.value for e in selected_experts],
            "expert_responses": expert_responses,
            "final_response": final_response,
            "suggested_followups": self._generate_followups(query_analysis, final_response)
        }

    def _analyze_query(self, query: str, context: Dict) -> Dict[str, Any]:
        """Analizar profundamente la consulta del usuario"""

        # Extraer intención
        intentions = self._extract_intentions(query)

        # Identificar dominios técnicos
        technical_domains = self._identify_technical_domains(query)

        # Determinar nivel de experiencia del usuario
        user_level = self._estimate_user_level(query, context)

        # Extraer requisitos implícitos
        implicit_requirements = self._extract_implicit_requirements(query)

        return {
            "raw_query": query,
            "intentions": intentions,
            "technical_domains": technical_domains,
            "user_experience_level": user_level,
            "implicit_requirements": implicit_requirements,
            "requires_code": self._requires_code_examples(query),
            "requires_diagrams": self._requires_diagrams(query),
            "urgency_level": self._determine_urgency(query),
            "project_scope": self._estimate_project_scope(query)
        }

    def _select_experts(self, query_analysis: Dict) -> List[ExpertDomain]:
        """Seleccionar expertos relevantes basados en el análisis"""

        selected = set()

        # Primera pasada: expertos específicos por dominio técnico
        for domain in query_analysis["technical_domains"]:
            if domain in self.experts:
                selected.add(domain)

        # Segunda pasada: verificar relevancia individual
        final_selection = []
        for domain in selected:
            expert = self.experts[domain]
            if expert.should_activate(
                query_analysis["raw_query"], 
                query_analysis
            ):
                final_selection.append(domain)

        # Si no hay expertos específicos, usar transdisciplinario por defecto
        if not final_selection and ExpertDomain.TRANSDISCIPLINARY in self.experts:
            final_selection.append(ExpertDomain.TRANSDISCIPLINARY)

        return final_selection

    def _get_expert_response(self, expert_domain: ExpertDomain, 
                           query: str, analysis: Dict) -> ExpertResponse:
        """Obtener respuesta del experto específico"""

        expert = self.experts[expert_domain]

        if expert_domain == ExpertDomain.WEB_DEVELOPMENT:
            return self._get_web_development_response(query, analysis)

        # Aquí se añadirían las respuestas de otros expertos
        # elif expert_domain == ExpertDomain.CANVA_SPECIALIST:
        #     return self._get_canva_response(query, analysis)

        # Respuesta por defecto
        return ExpertResponse(
            expert_domain=expert_domain,
            confidence=0.5,
            content="No se pudo generar una respuesta específica.",
            recommendations=[],
            related_concepts=[],
            follow_up_questions=[]
        )

    def _get_web_development_response(self, query: str, 
                                    analysis: Dict) -> ExpertResponse:
