        # Detectar tipo de consulta
        if any(word in query.lower() for word in ['carrera', 'aprender', 'ruta', 'roadmap']):
            return self._generate_career_response(query, analysis)

        elif any(word in query.lower() for word in ['arquitectura', 'diseño', 'patrón']):
            return self._generate_architecture_response(query, analysis)

        elif any(word in query.lower() for word in ['tecnología', 'comparar', 'elegir']):
            return self._generate_technology_comparison(query, analysis)

        elif any(word in query.lower() for word in ['problema', 'error', 'solución']):
            return self._generate_problem_solution(query, analysis)

        else:
            return self._generate_general_web_response(query, analysis)

