    def _synthesize_responses(self, responses: List[ExpertResponse], 
                            analysis: Dict) -> ExpertResponse:
        """Sintetizar múltiples respuestas de expertos"""

        # Ordenar por confianza
        responses.sort(key=lambda x: x.confidence, reverse=True)

        # Tomar la respuesta principal como base
        primary_response = responses[0]

        # Sintetizar contenido
        synthesized_content = f"# 🔄 **Análisis Multidisciplinario**\n\n"
        synthesized_content += f"**Consulta:** {analysis['raw_query'][:100]}...\n\n"

        # Añadir perspectivas de cada experto
        for i, response in enumerate(responses, 1):
            synthesized_content += f"## Perspectiva {i}: {response.expert_domain.value.replace('_', ' ').title()}\n"
            synthesized_content += f"*Confianza: {response.confidence:.0%}*\n\n"

            # Extraer puntos clave de cada respuesta
            key_points = self._extract_key_points(response.content)
            for point in key_points[:3]:  # Tomar 3 puntos clave por experto
                synthesized_content += f"• {point}\n"

            synthesized_content += "\n"

        # Añadir síntesis integrada
        synthesized_content += "## 💡 **Síntesis Integrada**\n\n"
        synthesized_content += self._generate_integrated_synthesis(responses, analysis)

        # Combinar recomendaciones y preguntas
        all_recommendations = []
        all_questions = []
        all_concepts = []

        for response in responses:
            all_recommendations.extend(response.recommendations)
            all_questions.extend(response.follow_up_questions)
            all_concepts.extend(response.related_concepts)

        # Eliminar duplicados
        all_recommendations = list(set(all_recommendations))[:5]
        all_questions = list(set(all_questions))[:5]
        all_concepts = list(set(all_concepts))[:10]

        return ExpertResponse(
            expert_domain=ExpertDomain.TRANSDISCIPLINARY,
            confidence=sum(r.confidence for r in responses) / len(responses),
            content=synthesized_content,
            recommendations=all_recommendations,
            related_concepts=all_concepts,
            follow_up_questions=all_questions
        )

