def _extract_intentions(self, query: str) -> List[str]:
    """Extraer intenciones de la consulta"""
    intentions = []

    intention_patterns = {
        "learn": [r'aprender', r'enseñar', r'curso', r'tutorial', r'cómo'],
        "compare": [r'comparar', r'diferencia', r'vs', r'mejor que'],
        "solve": [r'solución', r'problema', r'error', r'arreglar', r'debug'],
        "design": [r'diseñar', r'arquitectura', r'plan', r'estructura'],
        "choose": [r'elegir', r'seleccionar', r'recomendar', r'cuál'],
        "career": [r'carrera', r'trabajo', r'empleo', r'profesión']
    }

    query_lower = query.lower()
    for intention, patterns in intention_patterns.items():
        for pattern in patterns:
            if re.search(pattern, query_lower):
                intentions.append(intention)
                break

    return intentions if intentions else ["general_advice"]

def _identify_technical_domains(self, query: str) -> List[str]:
    """Identificar dominios técnicos mencionados"""
    domains = []

    tech_keywords = {
        "frontend": ["frontend", "react", "angular", "vue", "html", "css", "javascript"],
        "backend": ["backend", "node", "python", "java", "api", "servidor", "base de datos"],
        "devops": ["devops", "docker", "kubernetes", "aws", "despliegue", "ci/cd"],
        "database": ["base de datos", "mysql", "postgresql", "mongodb", "sql", "nosql"],
        "mobile": ["móvil", "android", "ios", "react native", "flutter"],
        "ai_ml": ["ia", "machine learning", "tensorflow", "python", "datos"]
    }

    query_lower = query.lower()
    for domain, keywords in tech_keywords.items():
        for keyword in keywords:
            if keyword in query_lower:
                domains.append(domain)
                break

    return domains

