## 🔧 **API DE INTEGRACIÓN**

```python
class MAXIMUSPRIMEIntegrationAPI:
    """
    API para integrar el sistema de orquestación en aplicaciones externas
    """

    def __init__(self, api_key: str):
        self.orchestrator = ExpertOrchestrationSystem()
        self.api_key = api_key
        self.sessions = {}

    def create_session(self, user_context: Dict) -> str:
        """Crear nueva sesión de consultas"""
        session_id = hashlib.md5(f"{api_key}{datetime.now()}".encode()).hexdigest()[:16]
        self.sessions[session_id] = {
            "context": user_context,
            "history": [],
            "preferences": {},
            "created_at": datetime.now()
        }
        return session_id

    def query_experts(self, session_id: str, query: str, 
                     options: Dict = None) -> Dict:
        """Consultar al sistema de expertos"""

        if session_id not in self.sessions:
            raise ValueError("Sesión no válida")

        session = self.sessions[session_id]

        # Añadir contexto de sesión
        context = {**session["context"], **(options or {})}

        # Procesar consulta
        result = self.orchestrator.process_query(query, context)

        # Actualizar historial
        session["history"].append({
            "query": query,
            "timestamp": datetime.now(),
            "experts_used": result["selected_experts"],
            "response_preview": result["final_response"].content[:200] if result["final_response"] else ""
        })

        return {
            "session_id": session_id,
            "query": query,
            "response": result["final_response"].to_markdown() if result["final_response"] else "",
            "experts_involved": result["selected_experts"],
            "recommendations": result["final_response"].recommendations if result["final_response"] else [],
            "follow_up_questions": result["final_response"].follow_up_questions if result["final_response"] else [],
            "confidence_score": result["final_response"].confidence if result["final_response"] else 0.0
        }

    def get_session_report(self, session_id: str) -> Dict:
        """Obtener reporte completo de la sesión"""
        session = self.sessions.get(session_id)
        if not session:
            raise ValueError("Sesión no válida")

        return {
            "session_id": session_id,
            "created_at": session["created_at"],
            "query_count": len(session["history"]),
            "experts_consulted": list(set(
                exp for entry in session["history"] 
                for exp in entry.get("experts_used", [])
            )),
            "history": session["history"],
            "recommended_next_steps": self._generate_next_steps(session)
        }
```

## 📊 **SISTEMA DE MONITOREO Y MEJORA**

```python
class ExpertPerformanceMonitor:
    """
    Sistema para monitorear y mejorar el rendimiento de expertos
    """

    def __init__(self, orchestrator: ExpertOrchestrationSystem):
        self.orchestrator = orchestrator
        self.performance_metrics = {}
        self.feedback_system = FeedbackCollector()

    def track_response_quality(self, query: str, response: ExpertResponse, 
                             user_feedback: Optional[Dict] = None):
        """Monitorear calidad de respuestas"""

        # Métricas automáticas
        automatic_metrics = {
            "response_length": len(response.content),
            "code_examples": len(response.code_examples) if response.code_examples else 0,
            "recommendations_count": len(response.recommendations),
            "confidence_score": response.confidence,
            "domain_match_score": self._calculate_domain_match(query, response.expert_domain)
        }

        # Métricas de usuario (si disponibles)
        if user_feedback:
            automatic_metrics.update({
                "user_satisfaction": user_feedback.get("rating", 0),
                "usefulness_score": user_feedback.get("usefulness", 0),
                "clarity_score": user_feedback.get("clarity", 0)
            })

        # Almacenar métricas
        expert_key = response.expert_domain.value
        if expert_key not in self.performance_metrics:
            self.performance_metrics[expert_key] = []

        self.performance_metrics[expert_key].append({
            "timestamp": datetime.now(),
            "metrics": automatic_metrics,
            "query_snippet": query[:100]
        })

    def generate_improvement_recommendations(self) -> Dict:
        """Generar recomendaciones para mejorar el sistema"""

        recommendations = {}

        for expert, metrics_list in self.performance_metrics.items():
            if len(metrics_list) < 5:  # Necesitamos datos suficientes
                continue

            # Calcular promedios
            avg_confidence = sum(m["metrics"]["confidence_score"] for m in metrics_list[-10:]) / 10
            avg_satisfaction = sum(m["metrics"].get("user_satisfaction", 0) for m in metrics_list[-10:]) / 10

            # Generar recomendaciones basadas en métricas
            expert_recommendations = []

            if avg_confidence < 0.6:
                expert_recommendations.append(
                    "Aumentar base de conocimiento para mejorar confianza en respuestas"
                )

            if avg_satisfaction < 3.0 and avg_satisfaction > 0:
                expert_recommendations.append(
                    "Revisar templates de respuesta para mayor claridad"
                )

            if expert_recommendations:
                recommendations[expert] = expert_recommendations

        return recommendations
